"""Generate html/<screen>.html for each screen defined in menu.json."""
import json
import os
from decimal import Decimal
from html import escape

DIR_PATH = os.path.dirname(os.path.realpath(__file__))
MENU_FILE = os.path.join(DIR_PATH, "menu.json")
HTML_DIR = os.path.join(DIR_PATH, "html")

PAGE = """<!DOCTYPE html>
<!-- GENERATED by build_menus.py from menu.json. Do not edit by hand; edit menu.json instead. -->
<html lang="en">
<head>
    <meta charset="UTF-8">
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=PT+Sans+Narrow:wght@400;700&display=swap" rel="stylesheet">
    <title>{title}</title>
    <link rel="stylesheet" href="css/style.css">
</head>
<body>
    <div class="screen">
        <aside class="sidebar">
{sidebar}
        </aside>
{columns}
    </div>
</body>
</html>
"""


def format_price(price):
    """6 -> '<span>$6</span>', '2.50' -> '<span>$2</span><span class="cents">50</span>'."""
    amount = Decimal(str(price)).quantize(Decimal("0.01"))
    dollars, cents = f"{amount:.2f}".split(".")
    html = f'<span class="dollars">${dollars}</span>'
    if cents != "00":
        html += f'<span class="cents">{cents}</span>'
    return html


def render_item(item):
    note = f' <span class="item-note">{escape(item["note"])}</span>' if item.get("note") else ""
    return (
        '                    <li class="item">\n'
        f'                        <span class="item-name">{escape(item["name"])}{note}</span>\n'
        f'                        <span class="item-price">{format_price(item["price"])}</span>\n'
        '                    </li>'
    )


def render_category(cat):
    items = "\n".join(render_item(i) for i in cat["items"])
    image = ""
    if cat.get("image"):
        image = (
            '                <div class="card-image">\n'
            f'                    <img src="{escape(cat["image"])}" alt="{escape(cat["title"])}">\n'
            '                </div>\n'
        )
    return (
        '            <section class="card">\n'
        f'                <h1 class="card-title">{escape(cat["title"])}</h1>\n'
        f'{image}'
        '                <ul class="items">\n'
        f'{items}\n'
        '                </ul>\n'
        '            </section>'
    )


def render_sidebar_entry(entry):
    if entry.get("image"):
        return f'            <img class="sidebar-image" src="{escape(entry["image"])}" alt="">'
    sub = f'\n                <p class="sidebar-subtext">{escape(entry["subtext"])}</p>' if entry.get("subtext") else ""
    return (
        '            <div class="sidebar-note">\n'
        f'                <p class="sidebar-text">{escape(entry["text"])}</p>{sub}\n'
        '            </div>'
    )


def render_screen(name, screen):
    columns = "\n".join(
        '        <div class="column">\n'
        + "\n".join(render_category(c) for c in column)
        + "\n        </div>"
        for column in screen["columns"]
    )
    sidebar = "\n".join(render_sidebar_entry(e) for e in screen.get("sidebar", []))
    return PAGE.format(title=escape(name), sidebar=sidebar, columns=columns)


def build(screens=None):
    """Write html/<screen>.html for the given screen names (all if None). Returns names built."""
    with open(MENU_FILE, encoding="utf-8") as f:
        menu = json.load(f)
    names = screens or list(menu["screens"])
    for name in names:
        with open(os.path.join(HTML_DIR, f"{name}.html"), "w", encoding="utf-8") as f:
            f.write(render_screen(name, menu["screens"][name]))
    return names


def screen_names():
    with open(MENU_FILE, encoding="utf-8") as f:
        return list(json.load(f)["screens"])


if __name__ == "__main__":
    print("Built:", ", ".join(build()))
